def rectangles_overlap(r1, r2):
    def x_overlap(a, b):
        return a[2] > b[1] and b[2] > a[1]
    def y_overlap(a, b):
        return a[3] > b[2] and b[3] > a[2]
    return x_overlap(r1, r2) and y_overlap(r1, r2)
